/** Stage 1 CLI for JSON prompt and ACP v1 stdio. */
public final class JiCli {
    private JiCli() {}

    public static void main(String[] args) throws Exception {
        int exit = run(args, System.getenv(), System.out, System.err);
        if (exit != 0) System.exit(exit);
    }

    static int run(String[] args, Map<String, String> environment, java.io.PrintStream stdout, java.io.PrintStream stderr) {
        return run(args, environment, stdout, stderr, null);
    }

    static int run(String[] args, Map<String, String> environment, java.io.PrintStream stdout,
                   java.io.PrintStream stderr, io.github.diodeme.ji.ai.ModelProvider provider) {
        if (args.length == 0) return usage(stderr);
        try {
            if ("prompt".equals(args[0])) return prompt(args, environment, stdout, stderr, provider);
            if ("acp".equals(args[0]) && Arrays.asList(args).contains("--stdio") && Arrays.asList(args).contains("v1")) {
                PermissionBroker permissions = new PermissionBroker(java.time.Clock.systemUTC());
                MemoryHostStore hostStore = new MemoryHostStore();
                try (var runtime = runtime(environment, permissions, hostStore);
                     var sessions = new SessionApplicationService(runtime);
                     var server = new AcpV1Server(System.in, stdout, sessions, permissions,
                             new PromptApplicationService(sessions, hostStore), model(environment))) {
                    server.run();
                }
                return 0;
            }
            return usage(stderr);
        } catch (IllegalArgumentException exception) {
            stderr.println("input.invalid");
            return 2;
        } catch (java.io.IOException exception) {
            stderr.println("internal.unexpected");
            return 1;
        } catch (RuntimeException exception) {
            stderr.println("internal.unexpected");
            return 1;
        }
    }

    private static int prompt(String[] args, Map<String, String> environment, java.io.PrintStream stdout,
                              java.io.PrintStream stderr, io.github.diodeme.ji.ai.ModelProvider provider) throws java.io.IOException {
        int jsonIndex = Arrays.asList(args).indexOf("--json");
        if (jsonIndex < 0 || args.length < 3) return usage(stderr);
        String message = String.join(" ", Arrays.copyOfRange(args, jsonIndex + 1, args.length));
        var denied = (PermissionDecider) (request, cancellation) -> java.util.concurrent.CompletableFuture.completedFuture(
                new PermissionDecider.Decision(request.permissionId(), request.revision(), request.revision() + 1,
                        PermissionDecider.Outcome.DENY, java.time.Instant.now()));
        try (var runtime = provider == null ? runtime(environment, denied)
                : new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                        .permissionDecider(denied).build()) {
            var session = runtime.newSession(new io.github.diodeme.ji.agent.SessionOptions(model(environment), "."));
            var result = session.prompt(message).completion().toCompletableFuture().join();
            var transcript = session.transcript().stream().map(item -> Map.of(
                    "id", item.id(), "role", item.role().name().toLowerCase(), "text", item.text())).toList();
            new ObjectMapper().writeValue(stdout, Map.of("schemaVersion", "1.0", "ok", true,
                    "sessionId", session.id(), "runId", result.runId(), "outcome", result.outcome().name().toLowerCase(),
                    "transcript", transcript));
            stdout.println();
        }
        return 0;
    }

    private static io.github.diodeme.ji.agent.AgentRuntime runtime(
            Map<String, String> environment, PermissionDecider permissionDecider) {
        return runtime(environment, permissionDecider, new MemorySessionStore());
    }

    private static io.github.diodeme.ji.agent.AgentRuntime runtime(
            Map<String, String> environment, PermissionDecider permissionDecider,
            io.github.diodeme.ji.session.SessionStore sessionStore) {
        String baseUrl = required(environment, "JI_LLM_BASE_URL");
        String configuredSecret = environment.getOrDefault("JI_LLM_API_KEY", "");
        CredentialReference reference = configuredSecret.isEmpty()
                ? CredentialReference.none()
                : new CredentialReference("cli-environment", CredentialReference.Type.API_KEY);
        var provider = OpenAiProvider.builder().baseUrl(baseUrl).credential(reference, request -> {
            char[] secret = configuredSecret.toCharArray();
            try {
                return java.util.concurrent.CompletableFuture.completedFuture(secret.length == 0
                        ? CredentialMaterial.none()
                        : CredentialMaterial.apiKey(SensitiveValue.of(secret)));
            } finally {
                Arrays.fill(secret, '\0');
            }
        }).build();
        return new AgentRuntimeBuilder().provider(provider).sessionStore(sessionStore)
                .permissionDecider(permissionDecider)
                .build();
    }

    private static ModelRef model(Map<String, String> environment) {
        return new ModelRef("openai", required(environment, "JI_LLM_MODEL"));
    }

    private static String required(Map<String, String> environment, String name) {
        String value = environment.get(name);
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " is required");
        return value;
    }

    private static int usage(java.io.PrintStream stderr) {
        stderr.println("usage: ji prompt --json <message> | ji acp --protocol v1 --stdio");
        return 2;
    }
}

